def resolve(path, cwd, links):
    # Initialize the current path and remaining components
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Split remaining into components, filtering empty and '.'
    components = []
    for part in remaining.split('/'):
        if part and part != '.':
            components.append(part)

    link_count = 0

    while components:
        component = components.pop(0)

        if component == '..':
            # Move to parent
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
        else:
            # Append component
            if current == '/':
                candidate = '/' + component
            else:
                candidate = current + '/' + component

            # Check if it's a symlink
            if candidate in links:
                link_count += 1
                if link_count > 8:
                    return None

                target = links[candidate]

                # Parse the target
                if target.startswith('/'):
                    current = '/'
                    target_remaining = target[1:]
                else:
                    # Target is relative to the directory containing the link
                    if candidate == '/':
                        current = '/'
                    else:
                        current = candidate.rsplit('/', 1)[0]
                    target_remaining = target

                # Split target into components
                target_components = []
                for part in target_remaining.split('/'):
                    if part and part != '.':
                        target_components.append(part)

                # Prepend target components to remaining components
                components = target_components + components
            else:
                current = candidate

    # Remove trailing slash unless it's root
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

